export function assertRecoveryPricePanelGeometry(svg,lang,kind,inline=false){
 const {nodes}=inspectRecoveryPriceSvg(svg,lang,kind,inline),fixture=PANEL_FIXTURES[`${kind}-${lang}`];
 const texts=nodes.filter(n=>jlrTag(n)==='text'),rects=nodes.filter(n=>jlrTag(n)==='rect'),groups=nodes.filter(n=>jlrTag(n)==='g');
 const coordinates=new Map();
 for(const[index,[text,metrics,spans,envelope]]of Object.entries(fixture.labels)){
  const n=texts[Number(index)],a=jlrAttrs(n);assert.equal(jlrText(n),text,'Panel glyph envelope matches exact label');
  assert.deepEqual(Object.fromEntries(Object.keys(metrics).map(key=>[key,a[key]])),metrics,'Panel glyph envelope matches pinned font and anchor');
  const x=jlrNumber(a.x),y=jlrNumber(a.y);
  assert.deepEqual(jlrChildren(n).map(child=>[jlrNumber(jlrAttrs(child).x)-x,jlrAttrs(child).dy,jlrText(child)]),spans,'Panel glyph envelope matches line breaks and relative anchors');
  coordinates.set(Number(index),[x+envelope[0],y+envelope[1],x+envelope[2],y+envelope[3]]);
 }
 let associations=0;
 for(const[id,originalBounds,strokeHalf,shape,indices]of fixture.panels){
  let bounds=originalBounds;
  if(shape[0]==='rect'){
   const a=jlrAttrs(rects[shape[1]]);bounds=['x','y','width','height'].map(key=>jlrNumber(a[key]??'0'));
   assert.ok(bounds[2]>0&&bounds[3]>0);assert.equal(a.stroke&&a.stroke!=='none'?jlrNumber(a['stroke-width'])/2:0,strokeHalf,'Measured panel stroke is unchanged');
  }else{
   const g=groups[shape[1]];assert.equal(jlrAttrs(g).transform,shape[2]);assert.deepEqual(jlrChildren(g).filter(n=>jlrTag(n)!=='#text').map(n=>[jlrTag(n),jlrAttrs(n)]),shape[3],'Measured transformed blood-bag path remains unchanged');
  }
  const[x,y,w,h]=bounds;
  for(const index of indices){const[l,t,r,b]=coordinates.get(index);assert.ok(l>x+strokeHalf&&t>y+strokeHalf&&r<x+w-strokeHalf&&b<y+h-strokeHalf,`Label stays inside internal panel ${id}`);associations++;}
 }
 return associations;
}
